import type { Metadata } from "next";
import { SITE } from "./config";

/** Generated by app/opengraph-image.tsx. */
const OG_IMAGE = "/opengraph-image";

/**
 * Metadata for one public page: title, description, canonical URL, Open
 * Graph and Twitter cards, with the shared share image.
 */
export function pageMeta({
  title,
  description,
  path,
  type = "website",
  noindex = false,
}: {
  title: string;
  description: string;
  path: string;
  type?: "website" | "article";
  noindex?: boolean;
}): Metadata {
  const fullTitle = path === "/" ? `${SITE.name}: ${SITE.category}` : `${title} | ${SITE.name}`;
  return {
    title: { absolute: fullTitle },
    description,
    alternates: { canonical: path },
    openGraph: {
      type,
      url: path,
      siteName: SITE.name,
      title: fullTitle,
      description,
      locale: "en_US",
      images: [{ url: OG_IMAGE, width: 1200, height: 630, alt: `${SITE.name}: ${SITE.category}` }],
    },
    twitter: { card: "summary_large_image", title: fullTitle, description, images: [OG_IMAGE] },
    robots: noindex ? { index: false, follow: true } : undefined,
  };
}
